CREATE TABLE IF NOT EXISTS "chemical" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"description" VARCHAR(255) NOT NULL,
	"UN_number" VARCHAR(4) NOT NULL,
	"risk_class_id" INTEGER NOT NULL,
	"status" BOOLEAN NOT NULL,
	"create_date" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"update_date" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "chemical_cargo" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"cargo_code" VARCHAR(255) NOT NULL,
	"chemical_id" INTEGER NOT NULL,
	"quantity" BIGINT NOT NULL,
	"measure_unity_id" INTEGER NOT NULL,
	"origin" VARCHAR(255) NOT NULL,
	"destination" VARCHAR(255) NOT NULL,
	"technical_manager_id" INTEGER NOT NULL,
	"required_documentation" INTEGER NOT NULL,
	"status" INTEGER NOT NULL,
	"delivery_date" DATE NOT NULL,
	"create_date" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"update_date" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "cargo_status" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"description" VARCHAR(255) NOT NULL,
	"create_date" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "risk_class" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"description" VARCHAR(255) NOT NULL,
	"create_date" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "measure_unity" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"description" VARCHAR(255) NOT NULL,
	"create_date" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "technical_manager" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"create_date" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "required_documentation" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"description" VARCHAR(255) NOT NULL,
	"create_date" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "logs" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"data" JSON NOT NULL,
	"date" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

ALTER TABLE "chemical"
ADD FOREIGN KEY("risk_class_id") REFERENCES "risk_class"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "chemical_cargo"
ADD FOREIGN KEY("chemical_id") REFERENCES "chemical"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "chemical_cargo"
ADD FOREIGN KEY("required_documentation") REFERENCES "required_documentation"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "chemical_cargo"
ADD FOREIGN KEY("measure_unity_id") REFERENCES "measure_unity"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "chemical_cargo"
ADD FOREIGN KEY("status") REFERENCES "cargo_status"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "chemical_cargo"
ADD FOREIGN KEY("tecnical_manager") REFERENCES "technical_manager"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;